refentry.refsect1:
&reftitle.description;
boolsocket_create_pair intdomain inttype intprotocol arraypair
socket_create_pair crea due socket connessi e indistinguibili e li memorizza in pair. Questa funzione è comunemente utilizzata nell'IPC (comunicazione tra processi).

&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     pair ora è un riferimento a un array di istanze di Socket;
     in precedenza era un riferimento a un array di resource.

  &reftitle.examples;



    Esempio di socket_create_pair


<?php
$sockets = array();

/* Su Windows occorre utilizzare AF_INET */
$domain = (strtoupper(substr(PHP_OS, 0, 3)) == 'WIN' ? AF_INET : AF_UNIX);

/* Configurazione della coppia di socket */
if (socket_create_pair($domain, SOCK_STREAM, 0, $sockets) === false) {
    echo "socket_create_pair non riuscita. Motivo: ".socket_strerror(socket_last_error());
}
/* Invio e ricezione dei dati */
if (socket_write($sockets[0], "ABCdef123\n", strlen("ABCdef123\n")) === false) {
    echo "socket_write() non riuscita. Motivo: ".socket_strerror(socket_last_error($sockets[0]));
}
if (($data = socket_read($sockets[1], strlen("ABCdef123\n"), PHP_BINARY_READ)) === false) {
    echo "socket_read() non riuscita. Motivo: ".socket_strerror(socket_last_error($sockets[1]));
}
var_dump($data);

/* Chiusura dei socket */
socket_close($sockets[0]);
socket_close($sockets[1]);
?>







    Esempio di IPC con socket_create_pair


<?php
$ary = array();
$strone = 'Messaggio dal padre.';
$strtwo = 'Messaggio dal figlio.';

if (socket_create_pair(AF_UNIX, SOCK_STREAM, 0, $ary) === false) {
    echo "socket_create_pair() non riuscita. Motivo: ".socket_strerror(socket_last_error());
}
$pid = pcntl_fork();
if ($pid == -1) {
    echo 'Impossibile eseguire il fork del processo.';
} elseif ($pid) {
    /*padre*/
    socket_close($ary[0]);
    if (socket_write($ary[1], $strone, strlen($strone)) === false) {
        echo "socket_write() non riuscita. Motivo: ".socket_strerror(socket_last_error($ary[1]));
    }
    if (socket_read($ary[1], strlen($strtwo), PHP_BINARY_READ) == $strtwo) {
        echo "Ricevuto $strtwo\n";
    }
    socket_close($ary[1]);
} else {
    /*figlio*/
    socket_close($ary[1]);
    if (socket_write($ary[0], $strtwo, strlen($strtwo)) === false) {
        echo "socket_write() non riuscita. Motivo: ".socket_strerror(socket_last_error($ary[0]));
    }
    if (socket_read($ary[0], strlen($strone), PHP_BINARY_READ) == $strone) {
        echo "Ricevuto $strone\n";
    }
    socket_close($ary[0]);
}
?>
